#include <algorithm>
#include <string>
#include <vector>

bool allowedChar(char32_t c)
{
    return (c >= U'a' && c <= U'z') || (c >= U'0' && c <= U'9') || c == U'_' || c == U'-';
}

std::string validateLevelName(const std::string& name, const std::vector<std::string>& existing)
{
    if (name.empty()) return "Give the level a name.";
    if (name.size() > 32) return "Keep the name to 32 characters.";
    for (unsigned char c : name) if (!allowedChar(c)) return "Use a-z, 0-9, _ and - only.";
    if (name[0] == '-' || name[0] == '_') return "Start the name with a letter or digit.";
    if (std::find(existing.begin(), existing.end(), name) != existing.end()) return "A level called " + name + " already exists.";
    return "";
}

unitTests:
TEST("allowed characters") { CHECK(allowedChar(U'a')); CHECK(allowedChar(U'z')); CHECK(allowedChar(U'7')); CHECK(allowedChar(U'_')); CHECK(allowedChar(U'-')); }
TEST("refused characters") { CHECK(!allowedChar(U'A')); CHECK(!allowedChar(U' ')); CHECK(!allowedChar(U'.')); CHECK(!allowedChar(U'é')); }
TEST("good names") { CHECK_EQ(validateLevelName("cave-2", { "cave-1" }), std::string("")); CHECK_EQ(validateLevelName("a", {}), std::string("")); }
TEST("each problem") {
    CHECK_EQ(validateLevelName("", {}), std::string("Give the level a name."));
    CHECK_EQ(validateLevelName(std::string(33, 'a'), {}), std::string("Keep the name to 32 characters."));
    CHECK_EQ(validateLevelName("Cave", {}), std::string("Use a-z, 0-9, _ and - only."));
    CHECK_EQ(validateLevelName("-cave", {}), std::string("Start the name with a letter or digit."));
    CHECK_EQ(validateLevelName("cave-1", { "cave-1" }), std::string("A level called cave-1 already exists."));
}
TEST("first problem wins") { CHECK_EQ(validateLevelName("_Bad Name", {}), std::string("Use a-z, 0-9, _ and - only.")); CHECK_EQ(validateLevelName(std::string(40, '_'), {}), std::string("Keep the name to 32 characters.")); }
TEST("exactly 32 is fine") { CHECK_EQ(validateLevelName(std::string(32, 'x'), {}), std::string("")); }

